import pytest
from hypothesis import example, given, strategies as st

from ledger.billing.allocate import allocate_cents


@pytest.mark.invariant("cents_conserved")
@given(
    total_cents=st.integers(min_value=-10**7, max_value=10**7),
    weights=st.lists(st.integers(min_value=1, max_value=1_000), min_size=1, max_size=8),
)
@example(total_cents=-100, weights=[1, 2])
def test_allocation_conserves_cents_for_refunds(total_cents, weights):
    assert sum(allocate_cents(total_cents, weights)) == total_cents
